<script>
document.addEventListener('DOMContentLoaded', function () {
  let lastScrollTop = 0;
  const header = document.querySelector('.header-logo-block');
  //const header_h = document.querySelector('header');
  const headerHeight = header.offsetHeight;

  const mobilepanel = document.querySelector('.rd-mobilepanel');


  window.addEventListener('scroll', function() {
    if (window.innerWidth < 1200) {
      const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
      
      if (scrollTop > headerHeight) {
        header.classList.add('fixed-header');
        mobilepanel.classList.add('fixed-mobilepanel');
      } else {
        header.classList.remove('fixed-header');
        mobilepanel.classList.remove('fixed-mobilepanel');
      }
      
      if (scrollTop < lastScrollTop) {
        document.body.classList.add('scrolled-up');
      } else {
        document.body.classList.remove('scrolled-up');
      }
      
      lastScrollTop = scrollTop <= 0 ? 0 : scrollTop;
    }
  });


